import unittest
from src import export

class ExportTests(unittest.TestCase):
    def test_custom_heading(self):
        export.set_heading('item', 'count')
        self.assertEqual(export.export_inventory([{'name':'Cup','quantity':2}]),
                         'item,count\nCup,2\n')

    def test_default_heading(self):
        self.assertEqual(export.export_inventory([{'name':'Cup','quantity':2}]),
                         'name,quantity\nCup,2\n')
